import { SessionStorage } from 'quasar';
import { type dynamicObj, $ } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { isUndefinedOrNull } from 'src/utils/general';
import { number_column_types, charges_table_extraction } from 'src/constants';
import { notify } from 'src/components/notifications/notify';
import { documentPOApiService } from 'src/services';

let columnDataStatusMap = new Map();

// dataType -> is-numeric. Avoids a toLowerCase() + array scan per cell per re-render.
const numberColumnTypeCache = new Map<string, boolean>();

export default {
  methods: {
    async init(this: any) {
      this.prepareLineMapping();
      this.checkAITableSetting();
      if (this.user_settings[charges_table_extraction]) {
        await this.prepareCostingElementDictionary();
      }
    },
    onDragOverWrapper(this: any, event: any, index: any, name: string) {
      if (name == 'id' || name == 'action_column') return;
      this.onDragOver(event, index);
    },
    allowedColumnSorting(column: any) {
      return column.name !== 'id' && column.name !== 'action_column';
    },
    isNumberColumn(column: any) {
      if (!column || !column.dataType) {
        return false;
      }
      const dataType = column.dataType as string;
      let isNumber = numberColumnTypeCache.get(dataType);
      if (isNumber === undefined) {
        isNumber = number_column_types.includes(dataType.toLowerCase());
        numberColumnTypeCache.set(dataType, isNumber);
      }
      return isNumber;
    },
    getColumnAlignment(this: any, column: any) {
      if (!column.dataType) {
        return '';
      }
      if (this.isNumberColumn(column)) {
        return 'text-right';
      }
    },
    dragover(event: any) {
      event.preventDefault();
    },
    prepareTableFromDropedSource(this: any) {
      let data = SessionStorage.getItem('DRAG_PO_NUMBER') as string;
      SessionStorage.remove('DRAG_PO_NUMBER');
      this.tableConversionHandler(data);
    },
    cancelTableDrop(this: any) {
      SessionStorage.remove('DRAG_PO_NUMBER');
      const event = new CustomEvent('table_drag_mode_flag_update', { detail: true });
      document.dispatchEvent(event);
    },
    dragenter(event: any) {
      var tr = event.target.closest('tr');
      if ((event.target.tagName == 'tr' && event.target.className == 'droptarget') || tr && tr.className && tr.className == 'droptarget') {
        //logInfo('dragenter inside', event.target, tr);
      }
    },
    lineItemDataLoaded(this: any, e: any) {
      if (!e || !e.detail) {
        return;
      }
      this.lineItemsloading = false;
      let data = e.detail;
      this.resetRows();
      this.apiData = data;
      if (!this.record.hasOwnProperty('use_lines_net_amount_for_matched_total')) {
        this.record.use_lines_net_amount_for_matched_total = false;
      }
      this.docId = this.apiData && this.apiData.doc_id ? this.apiData.doc_id : '';
      this.refactorApiData();
      this.triggerLineItemDataLoadedEvent();
      this.$nextTick(() => {
        // Table is behind v-if="hasLineItems()", so restore the height once rows exist.
        // Replaces the updated() hook that re-applied it on every re-render.
        if (typeof this.applyStoredHeight === 'function') {
          this.applyStoredHeight(this.tableId);
        }
        this.resetAndReInitColumnResize(this.tableId);
      });
    },
    triggerLineItemDataLoadedEvent() {
      const event = new CustomEvent('line_items_loaded', {});
      document.dispatchEvent(event);
    },
    savedSortedColumns(this: any) {
      const columnList: any = [];
      this.tableColumns = JSON.parse(JSON.stringify(this.tableColumns));
      this.tableColumns.forEach((element: any, index: number) => {
        columnList[element.name] = element;
        if (columnList[element.name]) {
          columnList[element.name]['org_index'] = index;
        }
      });
      this.updatedLineColumns(this.tableColumns);
    },
    async updatedLineColumns(this: any, columns: any) {
      try {
        this.showLoading();
        let line_key = this.line_table_columns + '_' + this.doctype;
        await this.updateSetting(line_key, JSON.stringify(columns));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    resetRows(this: any) {
      this.tableRows = [];
      this.lineDataObj = {} as dynamicObj;
    },
    refactorApiData(this: any) {
      // DONT CHANGE THE ORDER OF FUNCTIONS CALLS
      this.is_ai_table = this.isAI_TableExit(this.apiData);
      this.setFormatOptions();
      this.table_name = this.apiData.tables && this.apiData.tables.length > 0 && this.apiData.tables[0].hasOwnProperty('name') ? this.apiData.tables[0].name : '';
      this.prepareTableLayoutObj();
      this.getTableColumns();
      this.sortTableColumns();
      this.prepareTableRowsAndRowObj();
      this.validateLineItemColumns();
      this.restrictPOEditIfNotValidated();
      this.setConnectedLineItems();
    },
    async sortTableColumns(this: any) {
      await this.sortTableColumn();
      if (this.table_name === 'PO_CONVERTED_TABLE' || this.doc_attributes[this.custom_range_for_po_tolerance]) {
        const columnItem = { name: 'action_column', field: 'action_column', align: 'left', label: this.$t('actions'), is_mapped: false, org_index: '' };
        this.tableColumns.push(columnItem);
      }
    },
    callAutoMatch() {
      const event = new CustomEvent('trigger_auto_match', {});
      document.dispatchEvent(event);
    },
    prepareTableRowsAndRowObj(this: any) {
      this.tableRows = [];
      this.lineDataObj = {} as dynamicObj;
      let lineDataTemp = {} as dynamicObj;
      let costingElementDictionary = {} as dynamicObj;

      if (!this.apiData.tables || this.apiData.tables.length == 0 || !this.apiData.tables[0].hasOwnProperty('rows') || this.apiData.tables[0].rows.length == 0) {
        return;
      }

      Array.from(this.apiData.tables[0].rows).forEach((row: any) => {
        if (row.is_deleted === false) {
          if (row.parent_id) {
            let newRow: dynamicObj = {};
            Array.from(row.columns).forEach((column: any) => {
              newRow[column.name] = {} as dynamicObj;
              newRow[column.name].formatted_value = column.formatted_value;
              newRow[column.name].value = column.value;
            });
            newRow['costing_element'] = row.costing_element;
            if (!costingElementDictionary.hasOwnProperty(row.parent_id)) {
              costingElementDictionary[row.parent_id] = [];
            }
            costingElementDictionary[row.parent_id].push(newRow);
          } else {
            let newRow: dynamicObj = {};
            // One clone for the row; reuse its cloned columns below instead of cloning each
            // column a second time (was O(rows × columns) JSON round-trips).
            const clonedRow = JSON.parse(JSON.stringify(row));
            const clonedColumns = Array.isArray(clonedRow.columns)
              ? clonedRow.columns
              : [];
            lineDataTemp[row.id] = clonedRow;
            lineDataTemp[row.id].locations_list = [] as any;
            if (row.locations_list) {
              Array.from(row.locations_list).forEach((location: any) => {
                lineDataTemp[row.id].locations_list['page_' + location.page] = location;
              });
            }
            lineDataTemp[row.id].columns = {} as any;
            (row.columns as any[]).forEach((column: any, colIdx: number) => {
              // Already cloned as part of clonedRow.
              const clonedColumn =
                clonedColumns[colIdx] ?? JSON.parse(JSON.stringify(column));
              lineDataTemp[row.id].columns[column.name] = clonedColumn;
              clonedColumn.locations_list = [] as any;
              if (column.locations_list) {
                Array.from(column.locations_list).forEach((location: any) => {
                  clonedColumn.locations_list['page_' + location.page] = location;
                });
              }
              if (isUndefinedOrNull(column.formatted_value)) {
                column.formatted_value = '';
              }
              newRow[column.name] = column.formatted_value;
              this.prepareMapOfColumnHavingData(column);
            });
            this.addExtraColumnsInRow(lineDataTemp, newRow, row.id);
            newRow['id'] = row.id;
            newRow['show_charges'] = false;
            const is_additional_cost = row.hasOwnProperty('is_additional_cost') && row.is_additional_cost === true;
            if (!is_additional_cost) {
              this.tableRows.push(newRow);
            }
          }
        }
      });

      Object.assign(this.lineDataObj, lineDataTemp);
      this.setTotallineItem();
      this.setCostingRows(costingElementDictionary);
    },
    setCostingRows(this: any, costingElementDictionary: any) {
      for (let row of this.tableRows) {
        if (costingElementDictionary.hasOwnProperty(row.id)) {
          row.costingElements = costingElementDictionary[row.id];
          this.lineDataObj[row.id]['costingElements'] = costingElementDictionary[row.id];
        }
      }
    },
    prepareMapOfColumnHavingData(column: any) {
      if (columnDataStatusMap.has(column.name)) {
        if (columnDataStatusMap.get(column.name) === false) {
          if (column.formatted_value && column.formatted_value != null && column.formatted_value != '') {
            columnDataStatusMap.set(column.name, true);
          }
        }
      } else {
        if (column.formatted_value && column.formatted_value != null && column.formatted_value != '') {
          columnDataStatusMap.set(column.name, true);
        } else {
          columnDataStatusMap.set(column.name, false);
        }
      }
    },
    addExtraColumnsInRow(this: any, lineDataTemp: any, newRow: any, rowId: string) {
      for (let colName of this.layoutExtraColumns) {
        let newColumObj = {
          name: colName,
          value: '',
          content: '',
          locations: [],
          locations_list: [],
          formatted_value: '',
          is_extra_column: true,
        };
        lineDataTemp[rowId].columns[colName] = newColumObj;
        columnDataStatusMap.set(colName, false);
        newRow[colName] = '';
      }
    },
    async sortTableColumn(this: any) {
      let save_cols = await this.getColumns(this.line_table_columns + '_' + this.doctype) as dynamicObj[];
      if (save_cols) {
        let idColsIndex: any, actionColumnIndex: any;
        const temp = [] as any[];
        const tempNotExist = [] as any[];
        this.tableColumns.forEach((column: any, index: any) => {
          if (column.name === 'id') {
            idColsIndex = index;
          }
          if (column.name === 'action_column') {
            actionColumnIndex = index;
          }
          const savedColumn = save_cols.find((col: any) => col.name === column.name);
          let label = column.name;
          if (this.lineItemLayout.hasOwnProperty(column.name)) {
            label = this.lineItemLayout[column.name].lbl_to_display;
          }
          if (savedColumn) {
            savedColumn.label = label;
            temp.push(savedColumn);
          } else {
            column.label = label;
            tempNotExist.push(column);
          }
        });
        if (tempNotExist && tempNotExist.length > 0) {
          const totalLenght = temp.length;
          tempNotExist.forEach((column: any, index: number) => {
            temp.push({ ...column, org_index: totalLenght + parseInt(column.org_index) });
          });
        }
        this.tableColumns = temp.sort((a: any, b: any) => a.org_index - b.org_index);
        let columnItem = { name: 'id', field: 'id', align: 'left', label: '', is_mapped: false, org_index: '' };
        if (idColsIndex) {
          this.tableColumns.splice(idColsIndex, 1);
          this.tableColumns.unshift(columnItem);
        } else {
          this.tableColumns.unshift(columnItem);
        }
        if (actionColumnIndex) {
          this.tableColumns.splice(actionColumnIndex, 1);
        }
        return;
      }

      let columnSourceList = JSON.parse(JSON.stringify(this.tableColumns));
      let columnsWithEmptyData: any = [];
      this.tableColumns = [] as dynamicObj[];

      Array.from(columnSourceList).forEach((item: any, index: any) => {
        if (
          this.hasOriginalIndex(item.org_index, item) != true &&
          columnDataStatusMap.has(item.name) &&
          columnDataStatusMap.get(item.name) === false
        ) {
          columnsWithEmptyData.push(Object.assign({}, item));
        } else {
          this.tableColumns.push(Object.assign({}, item));
        }
      });
      columnsWithEmptyData.sort((a: any, b: any) => {
        let fa = a.field.toLowerCase(),
          fb = b.field.toLowerCase();
        if (fa < fb) { return -1; }
        if (fa > fb) { return 1; }
        return 0;
      });
      let columnItem = { name: 'id', field: 'id', align: 'left', label: '', is_mapped: false, org_index: '' };
      this.tableColumns.unshift(columnItem);
      Array.from(columnsWithEmptyData).forEach((item: any, index: any) => {
        this.tableColumns.push(Object.assign({}, item));
      });
    },
    validateLineItemColumns(this: any) {
      let hasError = false;
      if (this.tableColumns === undefined) {
        return;
      }
      for (const column of this.tableColumns) {
        let isValid = this.isColumnNameValid(column);
        if (!isValid) {
          column.error = true;
          hasError = true;
          continue;
        }
      }
      let newValidation = !hasError;
      if (this.validation_done === newValidation) {
        return;
      }
      this.validation_done = newValidation;
    },
    hasOriginalIndex(index: any, _item: any) {
      let hasIndex = false;
      if (index !== '') {
        hasIndex = true;
      }
      return hasIndex;
    },
    restrictPOEditIfNotValidated(this: any) {
      const hasLineItems = this.hasLineItems();
      if (!this.is_po_view || !hasLineItems) {
        return;
      }

      // const hasRowErrors = this.hasRowErrors();
      // const missingColumns = hasLineItems
      //   ? this.getMissingMandatoryColumns(this.apiData.tables, this.apiData.doc_type)
      //   : [];

      // Everything is valid: validated, has line items, no row errors, and no mandatory columns missing.
      if (this.validation_done && hasLineItems /*&& !hasRowErrors && missingColumns.length === 0 */) {
        return;
      }

      this.poEditRestrictMessage = '';

      if (!this.validation_done) {
        this.poEditRestrictMessage = this.$t('po_restrict_message_not_mapped');
      } 
      // else if (hasRowErrors) {
      //   this.poEditRestrictMessage = this.$t('VALIDATION_REQUIRED_FOR_TABLE');
      // } 
      // else if (!hasLineItems || missingColumns.length > 0) {
      //   this.poEditRestrictMessage = this.prepareMissingColumnsMessage(missingColumns);
      // }

      this.poEditRestrictDialog = true;
    },
    hasRowErrors(this: any) {

      if (this.record?.ignore_table_validation) {
        return false;
      }

      const rows = this.apiData?.tables?.[0]?.rows;
      if (!Array.isArray(rows)) {
        return false;
      }
      // Mirror setRowErrors / lineItemsErrorsRaw: a row has errors when it carries
      // at least one message that is not a COLUMN_NOT_MAPPED notice.
      return rows.some(
        (row: any) =>
          row.is_deleted === false &&
          Array.isArray(row.messages) &&
          row.messages.some(
            (msg: any) => msg.message && msg.message_code !== 'COLUMN_NOT_MAPPED',
          ),
      );
    },
    prepareMissingColumnsMessage(this: any, columns: string[]) {
      if (columns.length === 0) {
        return this.$t('po_restrict_message_not_items');
      }
      const translatedColumns = columns.map((column) => this.$t(column)).join(', ');
      return this.$t('po_restrict_message').replace(/%%column%%/g, translatedColumns);
    },
    isPurchaseOrderConnected(this: any, id: string) {
      return (this.po_connected_items.hasOwnProperty(id) || this.line_connected_items.hasOwnProperty(id)) ? true : false;
    },
    isPOColumnAvailable(this: any, po_line_id: string, column_name: string) {
      let is_column_in_table = false;
      if (this.tableColumns.length > 0) {
        for (let column of this.tableColumns) {
          if (column.name.toLowerCase() === column_name.toLowerCase()) {
            is_column_in_table = true;
          }
        }
      }
      if (!is_column_in_table) {
        return false;
      }
      if (!this.PODataObj[po_line_id].hasOwnProperty(column_name)) {
        return false;
      }
      return true;
    },
    async getLineItemQuantity(this: any, POItem: dynamicObj) {
      let quantity_col = 'quantity';
      let column_name = this.apiData.doc_type + '_QUANTITY_COL';
      const prefer_qty_column = await this.getSetting(column_name);
      if (prefer_qty_column !== undefined && prefer_qty_column !== '') {
        quantity_col = prefer_qty_column;
      }
      return String(POItem[quantity_col]);
    },
    dispatchConnectionSuccessEvent(data: any) {
      const event = new CustomEvent('po_connection_success', { detail: { data: data } });
      document.dispatchEvent(event);
    },
    dispatchConnectionRemoveEvent(data: any, isPoId: boolean) {
      const event = new CustomEvent('po_connection_remove', { detail: { data: data, isPoId: isPoId } });
      document.dispatchEvent(event);
    },
    convertToUSValue(value: string) {
      return value.replace(/,/g, '.');
    },
    mouseMoveHandler(this: any, e: any) {
      if (!this.po_dragging || !this.validation_done || this.wait) {
        return;
      }
    },
    getMatchingDisplayValue(this: any, key: string, value: string) {
      if (!value) return '-';
      if (String(key).toLowerCase().includes('date')) {
        return this.formatDateAccordingToPreference(value, true);
      }
      return value;
    },
    getConnectionInfo(this: any, id: string) {
      let connection_info = {} as { [k: string]: any };
      connection_info = this.po_connected_items.hasOwnProperty(id) ? this.po_connected_items[id] : {};
      return connection_info;
    },
    getConnectedinfoAttribute(this: any, id: string, property: string) {
      let connection_info = this.getConnectionInfo(id);
      if (!connection_info || Object.keys(connection_info).length === 0) {
        return {};
      }

      if (property == 'connection_details' && (connection_info.hasOwnProperty('matching_info') || connection_info.table_lines)) {
        let matching_info = connection_info.matching_info;

        if (connection_info.table_lines && connection_info.table_lines.length > 0) {
          const matchedLine = connection_info.table_lines.find((line: any) => line.table_line_id === id);
          if (matchedLine) {
            matching_info = matchedLine.matching_info;
          }
        }

        if (!matching_info) {
          return '';
        }

        const keysHtml = Object.entries(matching_info).map(([key, match]: [string, any]) => {
          if (match['is_matched'] === false) {
            const setProperty = `</b>
            <div style='padding-left: 10px'>
              ${this.$t(String(key).toLowerCase())} </b>
              <div style='padding-left: 10px'>
                <div> - ${this.$t('po')}: ${this.getMatchingDisplayValue(key, match['expected'])}</div>
                <div> - ${this.$t('line')}: ${this.getMatchingDisplayValue(key, match['actual'])}</div>
              </div>
            </div>
          `;
            return setProperty;
          }
        });
        return keysHtml.join('');
      } else {
        if (!connection_info.connection_details) {
          return '';
        }
        let keysHtml = Object.entries(connection_info.connection_details.split(',')).map(([key, match]: [string, any]) => {
          const setProperty = `</b>
          <div style='padding-left: 10px'>
            ${String(match)} </b>
          </div>
          `;
          return setProperty;
        });
        return keysHtml.join('');
      }
    },
    // Reassigning these Pinia refs patches the cells in place — no remount, so scroll
    // position survives on large tables.
    setConnectedLineItems(this: any) {
      this.po_connected_items = {} as dynamicObj;
      this.line_connected_items = {} as dynamicObj;
      let po_matching = this.getConnectedLineItems();
      if (po_matching.length == 0) {
        return;
      }
      for (let [index, record] of po_matching.entries()) {
        if (record.hasOwnProperty('table_line_id')) {
          this.po_connected_items[record.table_line_id] = record;
        } else if (record.hasOwnProperty('table_lines')) {
          for (let [sub_index, table_line] of record.table_lines.entries()) {
            this.po_connected_items[table_line.table_line_id] = record;
          }
        }
        if (record.hasOwnProperty('po_line_id')) {
          this.line_connected_items[record.po_line_id] = record;
        } else if (record.hasOwnProperty('sub_lines')) {
          for (let [index, po_sub_lines] of record.sub_lines.entries()) {
            this.line_connected_items[po_sub_lines.po_line_id] = record;
          }
        }
      }
    },
    getConnectedLineItems(this: any) {
      let po_matching = [] as dynamicObj[];
      if (!this.record) {
        return po_matching;
      }
      if (this.record.po_multi_matched) {
        po_matching = this.record.po_multi_matched;
      }
      return po_matching;
    },
    hasLineItems(this: any) {
      if (!this.tableRows || Object.keys(this.tableRows).length === 0) {
        return false;
      }
      return true;
    },
    isViewPo(this: any) {
      if (this.$route.fullPath.match(/po-matching/g)) {
        this.is_po_view = true;
      }
    },
    showlineHighlighted(this: any, id: string) {
      let connection_info = this.getConnectionInfo(id);
      if (!connection_info || Object.keys(connection_info).length === 0) {
        return;
      }
      const event = new CustomEvent('show_line_highlighted', { detail: connection_info });
      document.dispatchEvent(event);
    },
    scrollToHightlightedLine(this: any, id: string) {
      let connection_info = this.getConnectionInfo(id);
      if (!connection_info || Object.keys(connection_info).length === 0) {
        return;
      }
      const event = new CustomEvent('scroll_to_highlighted_line', { detail: connection_info });
      document.dispatchEvent(event);
    },
    removedLineHighlight(this: any, id: string) {
      let connection_info = this.getConnectionInfo(id);
      if (!connection_info || Object.keys(connection_info).length === 0) {
        return;
      }
      const event = new CustomEvent('removed_highlight', { detail: connection_info });
      document.dispatchEvent(event);
    },
    keyDownEvent(this: any, e: any) {
      if ((e.ctrlKey || e.altKey) && e.keyCode === 86 && this.hasLineItems()) {
        e.preventDefault();
        let selectedElement: Element | null = document.activeElement;
        if (!selectedElement || !selectedElement.classList.contains('droptarget')) {
          return;
        }
        this.drop(e);
        return;
      }
      if ((e.ctrlKey || e.metaKey) && e.shiftKey && (e.key === 'l' || e.key === 'L')) {
        e.preventDefault();
        const rows = ($('#line_item_table') as HTMLElement).querySelectorAll<HTMLElement>('.line-item-tr');
        if (rows.length == 0) {
          return;
        }
        let first_row = rows[0];
        first_row.contentEditable = 'true';
        first_row.focus();
        first_row.contentEditable = 'false';
      }
    },
    async goTolineItemsPage(this: any) {
      await this.removeCache();
      this.$router.push('/field_validation_v1/' + this.apiData.doc_id);
    },
    goToDashboard(this: any) {
      this.$router.push('/dashboard');
    },
    tableConversionHandler(this: any, po_numbers: any) {
      try {
        this.callApiForTableConversion(po_numbers);
      } catch (err) {
        notify.error('Error while displaying Page');
        logError(err);
        return;
      }
    },
    callApiForTableConversion(po_numbers: any) {
      const event = new CustomEvent('convert_pline_to_ltable', { detail: po_numbers });
      document.dispatchEvent(event);
    },
    dispatchEventToSaveTableChanges(this: any) {
      const event = new CustomEvent('update_table_data', { detail: this.apiData.tables });
      document.dispatchEvent(event);
    },
    inputValueChanges(this: any, column_name: string, rowId: string) {
      if (this.is_view_readonly) {
        return;
      }
      if (!(this.table_name === 'PO_CONVERTED_TABLE')) {
        return;
      }
      setTimeout(() => {
        this.lineDataObj[rowId]['columns'][column_name].value = this.lineDataObj[rowId]['columns'][column_name].formatted_value;
        this.updateJsonForLineItems(column_name, rowId);
      }, 0);
    },
    updateJsonForLineItems(this: any, column_name: string, rowId: string) {
      Array.from(this.apiData.tables[0].rows).forEach((row: any, index: any) => {
        if (rowId === row.id) {
          Array.from(row.columns).forEach((column: any, index: any) => {
            if (column.name === column_name) {
              this.apiData.tables[0].rows[index].columns[index] = this.lineDataObj[row.id].columns[column_name];
              return;
            }
          });
        }
      });
      this.dispatchEventToSaveTableChanges();
    },
    deleteLine(this: any, rowId: string) {
      if (this.is_view_readonly) {
        return;
      }
      Array.from(this.apiData.tables[0].rows).forEach((row: any, index: any) => {
        if (rowId === row.id) {
          row.is_deleted = true;
        }
      });
      let connection_info = this.po_connected_items.hasOwnProperty(rowId) ? this.po_connected_items[rowId] : {};
      this.removePOConnection(rowId, false);
      const event = new CustomEvent('delete_table_line', { detail: { tables: this.apiData.tables, connection_info: connection_info } });
      document.dispatchEvent(event);
    },
    getConnectionStatus(this: any, id: string) {
      let connection_info = this.getConnectionInfo(id);
      return connection_info['connection_status'] as string;
    },
    getConnectionStatusDetails(this: any, id: string) {
      return this.getConnectedinfoAttribute(id, 'connection_details');
    },
    getConnectionIcon(this: any, id: string): string {
      const status = this.getConnectionStatus(id);
      if (status == 'success') {
        return 'link';
      }
      if (status == 'not_matched' || status == 'mismatch') {
        return 'link_off';
      }
      return 'link';
    },
    getConnectionColor(this: any, id: string): string {
      const status = this.getConnectionStatus(id);
      if (status == 'success') {
        return 'success';
      }
      if (status == 'not_matched' || status == 'mismatch') {
        return 'mismatched';
      }
      return 'success';
    },
    getConnectionTitle(this: any, id: string) {
      const status = this.getConnectionStatus(id);
      if (status == 'success') {
        return this.$t('po_connected_match');
      }
      if (status == 'mismatch') {
        return this.$t('po_connected_mismatch');
      }
      if (status == 'line_item_only') {
        return this.$t('po_connected_self');
      }
    },
    initToleranceForm(this: any, item: any) {
      let itemNumber = item['ITEM_NUMBER'] ? item['ITEM_NUMBER'].formatted_value : '';
      let supplierItemNumber = item['SUPPLIER_ITEM_NUMBER'] ? item['SUPPLIER_ITEM_NUMBER'].formatted_value : '';
      if (!itemNumber && !supplierItemNumber) {
        notify.error(this.$t('CAN_NOT_SET_TOLERANCE'));
        return;
      }
      itemNumber = this.cleanItemNumber(itemNumber);
      supplierItemNumber = this.cleanItemNumber(supplierItemNumber);
      this.fillToleranceModel(itemNumber);
      this.toleranceModel.item_number = itemNumber;
      this.toleranceModel.supplier_item_number = item['SUPPLIER_ITEM_NUMBER'] ? item['SUPPLIER_ITEM_NUMBER'].formatted_value : '';
    },
    fillToleranceModel(this: any, itemNumber?: string, supplierItemNumber?: string) {
      if (itemNumber && this.hasToleranceForItem(itemNumber)) {
        this.toleranceModel = JSON.parse(JSON.stringify(this.getToleranceForItem(itemNumber)));
        return;
      }
      if (supplierItemNumber && this.hasToleranceForItem(supplierItemNumber)) {
        this.toleranceModel = JSON.parse(JSON.stringify(this.getToleranceForItem(supplierItemNumber)));
        return;
      }
      this.initToleranceModel();
    },
    async saveToleranceLevel(this: any) {
      try {
        if (this.is_view_readonly) {
          return;
        }
        if (!this.doc_attributes[this.custom_range_for_po_tolerance]) {
          return;
        }
        if (!this.validateToleranceForm()) {
          return;
        }
        let response: any;
        this.showLoading();
        response = await documentPOApiService.setItemTolerance(this.toleranceModel);
        this.setToleranceForItem(this.toleranceModel.item_number, this.toleranceModel);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    validateToleranceForm(this: any) {
      let is_valid = true;
      const tolerance = this.getToleranceForItem(this.toleranceModel.item_number);
      if (this.toleranceModel['quantity_tolerance_type'] == this.percent &&
        (this.toleranceModel['quantity_tolerance'] < 1 || this.toleranceModel['quantity_tolerance'] > 100)) {
        this.toleranceModel['quantity_tolerance'] = tolerance.quantity_tolerance;
        notify.error(this.$t('percentage_1_to_100'));
        is_valid = false;
      }
      if (this.toleranceModel['unit_price_tolerance_type'] == this.percent &&
        (this.toleranceModel['unit_price_tolerance'] < 1 || this.toleranceModel['unit_price_tolerance'] > 100)) {
        this.toleranceModel['unit_price_tolerance'] = tolerance.unit_price_tolerance;
        notify.error(this.$t('percentage_1_to_100'));
        is_valid = false;
      }
      if (!this.toleranceModel.item_number) {
        notify.error(this.$t('CAN_NOT_SET_TOLERANCE'));
        is_valid = false;
      }
      return is_valid;
    },
    checkAITableSetting(this: any) {
      this.ai_table_setting_flag = false;
      if (this.user_settings[this.AI_table_extraction_setting]) {
        this.ai_table_setting_flag = this.user_settings[this.AI_table_extraction_setting];
      }
    },
  },
};
