import { ref, Ref } from 'vue';
import { debounce } from 'quasar';
import { useResizeObserver } from '@vueuse/core';
import { useSettingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

type TableHeightResizeOptions = {
  settingKey: string;
  minHeight?: number;
  minWidth?: number;
  debounceTime?: number;
};

/**
 * Composable for handling table height resize with persistence
 * @param tableRef - Vue ref to the table element
 * @param options - Configuration options
 */
export function useTableHeightResize(
  tableRef: Ref<any>,
  options: TableHeightResizeOptions
) {
  const {
    settingKey,
    minHeight = 200,
    minWidth = 20,
    debounceTime = 1000
  } = options;

  const settings_store = useSettingStore();
  const { user_settings } = storeToRefs(settings_store);
  const { setUserPreferences } = settings_store;

  const applyStoredHeight = (elementId: string) => {
    const setting = user_settings.value[settingKey];
    let height = minHeight;

    if (setting) {
      try {
        const parsed = JSON.parse(setting);
        if (parsed && typeof parsed.height === 'number') {
          height = parsed.height;
        }
      } catch {
        // Malformed setting — fall back to minHeight rather than throw.
      }
    }

    const element = document.getElementById(elementId);
    if (element) {
      if (height < minHeight) {
        height = minHeight;
      }
      element.style.height = height + 'px';
    }
  };

  const initResizeObserver = () => {
    useResizeObserver(
      tableRef,
      debounce((entries: any) => {
        const entry = entries[0];

        // If setting exists and height difference is less than 10px, skip
        if (user_settings.value[settingKey]) {
          const tableSetting = JSON.parse(user_settings.value[settingKey]);
          if (Math.abs(tableSetting.height - entry.contentRect.height) < 10) {
            return;
          }
        }

        // Skip if dimensions are too small
        if (entry.contentRect.width < minWidth || entry.contentRect.height < minWidth) {
          return;
        }

        setUserPreferences(settingKey, JSON.stringify(entry.contentRect));
      }, debounceTime)
    );
  };

  return {
    applyStoredHeight,
    initResizeObserver,
    user_settings
  };
}
